"""手順2: arm.step のツリー名からHN11一式の帰属関節を特定する。"""
from __future__ import annotations

import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[3]
CADRE = REPO / "skills" / "cad-reverse-parametric"
sys.path.insert(0, str(CADRE / "studies" / "xl430_lowcost"))
sys.path.insert(0, str(CADRE / "studies" / "follower_geometry_revision" / "source"))

from assembly_io import read_step  # noqa: E402

doc, st, rows = read_step(REPO / "hardware" / "follower" / "step" / "arm.step")
print("rows:", len(rows))

targets = {672.764: "hn11_rotor", 207.156: "hn11_cap", 39.291: "hn11_third"}
print("== HN11 solids by volume ==")
for r in rows:
    v = round(r.world.Volume(), 3)
    if v in targets:
        b = r.world.BoundingBox()
        print(f"{r.index:3d} {targets[v]:10s} min({b.xmin:8.3f},{b.ymin:8.3f},{b.zmin:8.3f}) "
              f"zlen {b.zlen:7.3f} xlen {b.xlen:7.3f} path {r.path}")

print("== IDLER occurrences ==")
for r in rows:
    if "IDLER" in r.path.upper():
        print(f"{r.index:3d} vol {r.world.Volume():8.3f} path {r.path}")

print("== motor instances (XL-430 subtree) ==")
prefixes = {}
for r in rows:
    if "XL-430" in r.path:
        key = r.path.split("XL-430")[0] + "XL-430" + r.path.split("XL-430")[1].split("/")[0]
        prefixes[key] = prefixes.get(key, 0) + 1
for k, v in sorted(prefixes.items()):
    print(v, k)

print("== top-level joints ==")
joints = {}
for r in rows:
    parts = r.path.strip("/").split("/")
    if len(parts) >= 2:
        key = "/".join(parts[:2])
        joints[key] = joints.get(key, 0) + 1
for k, v in sorted(joints.items()):
    print(v, k)

"""手順2: arm.step 上の2つのHN11配置について、軸に沿う相手部品の穴径・厚さを測る。"""
from __future__ import annotations

import sys
from pathlib import Path

import cadquery as cq
from OCP.BRepAdaptor import BRepAdaptor_Surface
from OCP.GeomAbs import GeomAbs_SurfaceType

REPO = Path(__file__).resolve().parents[2]
CADRE = REPO / "skills" / "cad-reverse-parametric"
sys.path.insert(0, str(CADRE / "studies" / "xl430_lowcost"))
sys.path.insert(0, str(CADRE / "studies" / "follower_geometry_revision" / "source"))

from assembly_io import read_step  # noqa: E402

# 各インスタンスのアイドラ軸: origin + t*dir （tはmm）
INSTANCES = {
    "XL-430_new v1:1 (HN11.step抽出元)": {
        "origin": (5.45, 116.604, -100.187),
        "dir": (0.0, 0.0, 1.0),
        "t_range": (-30.0, 30.0),
    },
    "XL-430_new v1:2 (応急案の対象)": {
        "origin": (22.5, 116.604, -46.637),
        "dir": (1.0, 0.0, 0.0),
        "t_range": (-30.0, 30.0),
    },
}
IDLER_TOKENS = ("IDLER_DUMMY", "IDLER_CAP", "IDLER_SCREW")

doc, st, rows = read_step(REPO / "hardware" / "follower" / "step" / "arm.step")


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1], a[2] - b[2])


def coaxial_cylinders(shape, origin, direction):
    out = []
    for f in shape.Faces():
        surf = BRepAdaptor_Surface(f.wrapped)
        if surf.GetType() != GeomAbs_SurfaceType.GeomAbs_Cylinder:
            continue
        cyl = surf.Cylinder()
        d = cyl.Axis().Direction()
        if abs(abs(dot((d.X(), d.Y(), d.Z()), direction)) - 1.0) > 1e-4:
            continue
        p = cyl.Axis().Location()
        offset = sub((p.X(), p.Y(), p.Z()), origin)
        radial = sub(offset, tuple(dot(offset, direction) * c for c in direction))
        if dot(radial, radial) > (0.01 ** 2):
            continue
        b = f.BoundingBox()
        ts = []
        for x in (b.xmin, b.xmax):
            for y in (b.ymin, b.ymax):
                for z in (b.zmin, b.zmax):
                    ts.append(dot(sub((x, y, z), origin), direction))
        out.append({"dia": 2 * float(cyl.Radius()), "t_min": min(ts), "t_max": max(ts),
                    "face_center": tuple(round(v, 4) for v in (f.Center().x, f.Center().y, f.Center().z))})
    return out


for label, inst in INSTANCES.items():
    origin = inst["origin"]
    direction = inst["dir"]
    print("=" * 20, label)
    for row in rows:
        if any(tok in row.path for tok in IDLER_TOKENS):
            continue
        b = row.world.BoundingBox()
        corners_t = [dot(sub((x, y, z), origin), direction)
                     for x in (b.xmin, b.xmax) for y in (b.ymin, b.ymax)
                     for z in (b.zmin, b.zmax)]
        if max(corners_t) < inst["t_range"][0] or min(corners_t) > inst["t_range"][1]:
            continue
        # 軸から半径15mm以内にbboxが来る候補だけ詳細を見る
        radial_ok = False
        for x in (b.xmin, b.xmax):
            for y in (b.ymin, b.ymax):
                for z in (b.zmin, b.zmax):
                    q = sub((x, y, z), origin)
                    radial = sub(q, tuple(dot(q, direction) * c for c in direction))
                    if dot(radial, radial) < 20.0 ** 2:
                        radial_ok = True
        if not radial_ok:
            continue
        cyls = coaxial_cylinders(row.world, origin, direction)
        if not cyls:
            continue
        merged = {}
        for c in cyls:
            key = round(c["dia"], 3)
            merged.setdefault(key, []).append(c)
        print(f"row {row.index:3d} vol {row.world.Volume():9.2f} {row.path}")
        for dia, cs in sorted(merged.items()):
            tmin = min(c["t_min"] for c in cs)
            tmax = max(c["t_max"] for c in cs)
            print(f"    dia {dia:7.3f} faces {len(cs)} t [{tmin:8.3f}, {tmax:8.3f}] span {tmax - tmin:6.3f}")

